INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`) VALUES
(64600, 'zhCN', '当你的手触上神龛的表面、与它的力量共鸣时，神龛似乎察觉到了你的存在。'),(9990200, 'zhCN', '英雄副本的所有装备，按部位分类。$b$b挑你想要的那件吧，$n。'),(9990220, 'zhCN', '神话副本的所有装备，按部位分类。$b$b挑你想要的那件吧，$n。'),(9990300, 'zhCN', '所有世界铸护甲与世界铸盾牌，按部位分类。$b$b挑你想要的那件吧，$n。'),(9990320, 'zhCN', '所有世界铸武器，按类型分类。$b$b挑你想要的那件吧，$n。'),(9990340, 'zhCN', '所有世界铸项链、披风、戒指、饰品、副手、遗物与背包。$b$b挑你想要的那件吧，$n。'),(9990400, 'zhCN', '药水、药剂、合剂、卷轴、食物、附魔与绷带，按类型与等级分类。$b$b挑你想要的那件吧，$n。'),(9990500, 'zhCN', '这个国度是用于测试的，$n。我可以把你提升到我们测试所用的最高等级，这样你就能直接开始。'),(9990501, 'zhCN', '在这个国度我没有东西可以给你，$n。')
ON DUPLICATE KEY UPDATE `Text0_0` = VALUES(`Text0_0`);

